commit e6717229564cae6e2f534526b52a3ed4af2ec5ff
Author:     Justin Tracey <jtracey@thunderbird.net>
AuthorDate: Thu Aug 7 17:49:34 2025 -0400
Commit:     Justin Tracey <jtracey@thunderbird.net>
CommitDate: Thu Aug 7 17:49:34 2025 -0400

    Bug 1937746 - Break early when mork cursors fail. r=kaie


    This shouldn't result in any behavioral changes, though technically if there is
    a logic bug hidden somewhere else, this could trigger undefined behavior (in
    which case, anything is possible, but it seems unlikely it would do anything
    different).

    Differential Revision: https://phabricator.services.mozilla.com/D259999

diff --git a/mailnews/db/msgdb/src/nsMailDatabase.cpp b/mailnews/db/msgdb/src/nsMailDatabase.cpp
index dad78272d99..5712050eb55 100644
--- a/mailnews/db/msgdb/src/nsMailDatabase.cpp
+++ b/mailnews/db/msgdb/src/nsMailDatabase.cpp
@@ -6,14 +6,13 @@
 #include "msgCore.h"
 #include "nsMailDatabase.h"
 #include "nsDBFolderInfo.h"
+#include "nsError.h"
 #include "nsNetUtil.h"
 #include "nsMsgOfflineImapOperation.h"
 #include "nsMsgFolderFlags.h"
 #include "mozilla/Logging.h"
-#include "prprf.h"
 #include "nsMsgUtils.h"
 #include "nsIMsgPluggableStore.h"
-#include "nsSimpleEnumerator.h"

 using namespace mozilla;

@@ -231,18 +230,18 @@ NS_IMETHODIMP nsMailDatabase::ListAllOfflineOpIds(

       err = rowCursor->NextRowOid(GetEnv(), &outOid, &outPos);
       // is this right? Mork is returning a 0 id, but that should valid.
-      if (outPos < 0 || outOid.mOid_Id == (mdb_id)-1) break;
-      if (NS_SUCCEEDED(err)) {
-        offlineOpIds.AppendElement(outOid.mOid_Id);
-        if (MOZ_LOG_TEST(IMAPOffline, LogLevel::Info)) {
-          nsCOMPtr<nsIMsgOfflineImapOperation> offlineOp;
-          GetOfflineOpForKey(outOid.mOid_Id, false, getter_AddRefs(offlineOp));
-          if (offlineOp) {
-            nsMsgOfflineImapOperation* logOp =
-                static_cast<nsMsgOfflineImapOperation*>(
-                    static_cast<nsIMsgOfflineImapOperation*>(offlineOp.get()));
-            if (logOp) logOp->Log();
-          }
+      if (NS_FAILED(err) || outPos < 0 || outOid.mOid_Id == (mdb_id)-1) {
+        break;
+      }
+      offlineOpIds.AppendElement(outOid.mOid_Id);
+      if (MOZ_LOG_TEST(IMAPOffline, LogLevel::Info)) {
+        nsCOMPtr<nsIMsgOfflineImapOperation> offlineOp;
+        GetOfflineOpForKey(outOid.mOid_Id, false, getter_AddRefs(offlineOp));
+        if (offlineOp) {
+          nsMsgOfflineImapOperation* logOp =
+              static_cast<nsMsgOfflineImapOperation*>(
+                  static_cast<nsIMsgOfflineImapOperation*>(offlineOp.get()));
+          if (logOp) logOp->Log();
         }
       }
     }
@@ -270,23 +269,23 @@ NS_IMETHODIMP nsMailDatabase::ListAllOfflineDeletes(

       err = rowCursor->NextRow(GetEnv(), &offlineOpRow, &outPos);
       // is this right? Mork is returning a 0 id, but that should valid.
-      if (outPos < 0 || offlineOpRow == nullptr) break;
-      if (NS_SUCCEEDED(err)) {
-        offlineOpRow->GetOid(GetEnv(), &outOid);
-        RefPtr<nsIMsgOfflineImapOperation> offlineOp =
-            new nsMsgOfflineImapOperation(this, offlineOpRow);
-        imapMessageFlagsType newFlags;
-        nsOfflineImapOperationType opType;
-
-        offlineOp->GetOperation(&opType);
-        offlineOp->GetNewFlags(&newFlags);
-        if (opType & nsIMsgOfflineImapOperation::kMsgMoved ||
-            ((opType & nsIMsgOfflineImapOperation::kFlagsChanged) &&
-             (newFlags & nsIMsgOfflineImapOperation::kMsgMarkedDeleted)))
-          offlineDeletes.AppendElement(outOid.mOid_Id);
-
-        offlineOpRow->Release();
+      if (NS_FAILED(err) || outPos < 0 || offlineOpRow == nullptr) {
+        break;
       }
+      offlineOpRow->GetOid(GetEnv(), &outOid);
+      RefPtr<nsIMsgOfflineImapOperation> offlineOp =
+          new nsMsgOfflineImapOperation(this, offlineOpRow);
+      imapMessageFlagsType newFlags;
+      nsOfflineImapOperationType opType;
+
+      offlineOp->GetOperation(&opType);
+      offlineOp->GetNewFlags(&newFlags);
+      if (opType & nsIMsgOfflineImapOperation::kMsgMoved ||
+          ((opType & nsIMsgOfflineImapOperation::kFlagsChanged) &&
+           (newFlags & nsIMsgOfflineImapOperation::kMsgMarkedDeleted)))
+        offlineDeletes.AppendElement(outOid.mOid_Id);
+
+      offlineOpRow->Release();
     }
     // TODO: would it cause a problem to replace this with "rv = err;" ?
     rv = (NS_SUCCEEDED(err)) ? NS_OK : NS_ERROR_FAILURE;
diff --git a/mailnews/db/msgdb/src/nsMsgDatabase.cpp b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
index 879e3889909..ebb00c0dc3a 100644
--- a/mailnews/db/msgdb/src/nsMsgDatabase.cpp
+++ b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
@@ -8,6 +8,7 @@
 #include "nsMsgDatabase.h"

 #include "MailNewsTypes.h"
+#include "nsError.h"
 #include "nscore.h"
 #include "msgCore.h"
 #include "nsIFile.h"
@@ -2866,13 +2867,11 @@ NS_IMETHODIMP nsMsgDatabase::ListAllKeys(nsTArray<nsMsgKey>& keys) {

       rv = rowCursor->NextRowOid(GetEnv(), &outOid, &outPos);
       // is this right? Mork is returning a 0 id, but that should valid.
-      if (outPos < 0 || outOid.mOid_Id == (mdb_id)-1) {
+      if (NS_FAILED(rv) || outPos < 0 || outOid.mOid_Id == (mdb_id)-1) {
         break;
       }

-      if (NS_SUCCEEDED(rv)) {
-        keys.AppendElement(outOid.mOid_Id);
-      }
+      keys.AppendElement(outOid.mOid_Id);
     }
   }
   return rv;
